//! In-process HTTP server for the runtime's own artifacts.
//!
//! ## Why this lives here
//!
//! Files generated by the agent (HTML, CSS, JS, sometimes Python/Node source)
//! must NEVER cross the runtime's trust boundary. When the runtime runs inside
//! a sandbox, the artifact files stay in the sandbox; when it runs on the host,
//! they live on the host. Either way: the same process that *wrote* the files
//! is also the one that *serves* them, so the data path never escapes.
//!
//! The user-facing entry point (`localhost:7800`) lives in the **orchestrator**
//! (`x0ne-orchestrator/src/artifact_local_proxy.rs`), which reverse-proxies
//! HTTP requests to whichever runtime owns the artifact. That keeps the
//! orchestrator pure-routing (no agent-generated bytes touch its disk or its
//! parent process's memory in a way that could be auto-executed).
//!
//! ## Bind address
//!
//! - **Host mode**: `127.0.0.1:<port>` — only loopback, only the orchestrator
//!   on the same host talks to us.
//! - **Sandbox mode** (`X0NE_ALLOW_LOOPBACK=1`): `0.0.0.0:<port>` so the
//!   orchestrator running on the host can reach us via the container's bridge
//!   IP. The container's network is the only escape vector — limited to L7
//!   HTTP, no filesystem hop.
//!
//! Override the port with `X0NE_RUNTIME_SERVE_PORT` (default `7900`; `0` binds
//! an ephemeral port, for tests).
//!
//! ## Hardening
//!
//! The same guard as the router's (audit of 2026-10-30, H3-1): `GET` and
//! `HEAD` only; a `Host` that names this machine with the bound port (a
//! loopback spelling, or an IP literal, which is how the router reaches a
//! sandboxed runtime across the container bridge: a DNS rebinding attack
//! sends a name); an `Origin`, when a browser sends one, on such a host; no
//! cross-site embedding. Every answer carries the headers that keep an
//! artifact page in its place, `/_api/artifacts` reports a count, a service
//! artifact gets `GET`/`HEAD` with allowlisted headers and no body.
//!
//! `serve_static` canonicalises the requested path and rejects anything that
//! escapes `cv.root_path` via `..` or symlinks (an agent-generated symlink to
//! the password file returns 403 instead of leaking).

use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use axum::{
    body::Body,
    extract::{Path as AxPath, Request, State},
    http::{header, HeaderMap, HeaderValue, Method, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Response},
    routing::{any, get},
    Json, Router,
};
use serde_json::json;
use tokio::sync::RwLock;
use tracing::{info, warn};
use x0ne_actions::http_guard::HostPolicy;
use x0ne_artifact::{self as artifact, Artifact, ArtifactKind, ArtifactRegistry};

/// Default port the runtime's serving HTTP listens on. Reserved range starts
/// at 7900 (well above the 7810-7899 service-artifact range).
pub const DEFAULT_RUNTIME_SERVE_PORT: u16 = 7900;

#[derive(Clone)]
struct Ctx {
    /// Address advertised back to the orchestrator (e.g. `127.0.0.1:7900` on
    /// host, `0.0.0.0:7900` in sandbox).
    advertised_port: u16,
    http: reqwest::Client,
    cache: Arc<RwLock<Option<ArtifactRegistry>>>,
}

/// Spawn the serving HTTP app on a tokio task. Returns the bound address (or
/// an error if the port is busy / privilege mismatch). Best-effort: the caller
/// should log and continue if startup fails — artifact creation still works,
/// the URLs just won't be reachable.
pub async fn spawn() -> Result<SocketAddr, std::io::Error> {
    let port = std::env::var("X0NE_RUNTIME_SERVE_PORT")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(DEFAULT_RUNTIME_SERVE_PORT);

    // Sandbox: bind 0.0.0.0 so the orchestrator (on the host) can reach us via
    // the container's bridge IP. Host: bind 127.0.0.1 — only the local
    // orchestrator talks to us.
    let bind_ip = if artifact::running_in_sandbox() {
        "0.0.0.0"
    } else {
        "127.0.0.1"
    };
    let addr: SocketAddr = format!("{}:{}", bind_ip, port).parse().map_err(|e| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("bind addr parse: {}", e),
        )
    })?;

    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(l) => l,
        Err(e) => {
            warn!(?addr, "artifact serve cannot bind: {}", e);
            return Err(e);
        }
    };
    let bound = listener.local_addr()?;

    let ctx = Ctx {
        advertised_port: bound.port(),
        http: reqwest::Client::builder()
            .timeout(Duration::from_secs(60))
            .redirect(reqwest::redirect::Policy::none())
            .build()
            .unwrap(),
        cache: Arc::new(RwLock::new(None)),
    };

    let app = app(ctx);

    info!("x0ne-runtime artifact serve listening on http://{}", bound);
    tokio::spawn(async move {
        if let Err(e) = axum::serve(listener, app).await {
            warn!("artifact serve loop ended: {}", e);
        }
    });

    Ok(bound)
}

fn app(ctx: Ctx) -> Router {
    Router::new()
        .route("/_health", get(health))
        .route("/_api/artifacts", get(api_list))
        .route("/a/{id}", any(artifact_root))
        .route("/a/{id}/", any(artifact_root))
        .route("/a/{id}/{*rest}", any(artifact_path))
        .layer(middleware::from_fn_with_state(ctx.clone(), guard))
        .with_state(ctx)
}

// ── Guard ────────────────────────────────────────────────────────────────────

/// Audit of 2026-10-30, H3-1. The router on 7800 got this guard first; this
/// server answered whatever reached its port, and its port is in the URLs it
/// printed: a page whose name resolves to 127.0.0.1 read an artifact under
/// its own `Host`, any method and body went to a service artifact.
async fn guard(State(ctx): State<Ctx>, req: Request, next: Next) -> Response {
    if let Err(refused) = admit(ctx.advertised_port, req.method(), req.headers()) {
        return refused;
    }
    let mut resp = next.run(req).await;
    protect(resp.headers_mut());
    resp
}

/// `GET` or `HEAD`; a `Host` that names this machine with the bound port; an
/// `Origin`, when the browser sends one, on such a host; without one, a
/// cross-site request only as a top-level navigation (a link the user
/// follows), never as an embedded image, script or frame.
fn admit(port: u16, method: &Method, headers: &HeaderMap) -> Result<(), Response> {
    if *method != Method::GET && *method != Method::HEAD {
        return Err((
            StatusCode::METHOD_NOT_ALLOWED,
            [(header::ALLOW, "GET, HEAD")],
            "artifacts are read with GET or HEAD only",
        )
            .into_response());
    }
    let get = |name: &str| headers.get(name).and_then(|v| v.to_str().ok());
    if !get("host").is_some_and(|h| names_this_machine(h, port)) {
        return Err((
            StatusCode::FORBIDDEN,
            "artifacts answer this machine only (Host)",
        )
            .into_response());
    }
    match get("origin") {
        Some(origin) => {
            let local = origin
                .strip_prefix("http://")
                .is_some_and(|h| names_this_machine(h, port));
            if !local {
                return Err((
                    StatusCode::FORBIDDEN,
                    "artifacts answer this machine's browser only (Origin)",
                )
                    .into_response());
            }
        }
        None => {
            let cross_site =
                get("sec-fetch-site").is_some_and(|v| v.eq_ignore_ascii_case("cross-site"));
            let navigation = get("sec-fetch-mode")
                .is_some_and(|v| v.eq_ignore_ascii_case("navigate"))
                && get("sec-fetch-dest").is_some_and(|v| v.eq_ignore_ascii_case("document"));
            if cross_site && !navigation {
                return Err((
                    StatusCode::FORBIDDEN,
                    "a page from another site cannot embed or read an artifact",
                )
                    .into_response());
            }
        }
    }
    Ok(())
}

/// `host` is `<host>:<port>` for this server: a loopback spelling, or an IP
/// literal (the router reaches a sandboxed runtime by the container's bridge
/// address; a DNS rebinding attack sends a name), with the bound port.
fn names_this_machine(host: &str, port: u16) -> bool {
    if HostPolicy::loopback(port).check(Some(host)).is_ok() {
        return true;
    }
    let (ip, p) = if let Some(rest) = host.strip_prefix('[') {
        let Some(split) = rest.split_once("]:") else {
            return false;
        };
        split
    } else {
        let Some(split) = host.rsplit_once(':') else {
            return false;
        };
        split
    };
    p.parse::<u16>().ok() == Some(port) && ip.parse::<std::net::IpAddr>().is_ok()
}

/// Headers on every answer, static or forwarded. `Cross-Origin-Resource-Policy:
/// same-origin`: measured on Chromium 156 (2026-10-31), `same-site` already
/// kept a `localhost` page from embedding a `127.0.0.1` resource and the
/// reverse, but let a `localhost` page of any port embed one of this server;
/// an artifact's files are its own.
fn protect(h: &mut HeaderMap) {
    h.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    h.insert(
        header::REFERRER_POLICY,
        HeaderValue::from_static("no-referrer"),
    );
    h.insert(
        "cross-origin-resource-policy",
        HeaderValue::from_static("same-origin"),
    );
    h.append(
        header::CONTENT_SECURITY_POLICY,
        HeaderValue::from_static("frame-ancestors 'none'"),
    );
    h.insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
}

// ── Handlers ─────────────────────────────────────────────────────────────────

async fn health() -> impl IntoResponse {
    (StatusCode::OK, "ok")
}

async fn refresh_cache(ctx: &Ctx) -> ArtifactRegistry {
    let reg = artifact::load_registry().unwrap_or_default();
    *ctx.cache.write().await = Some(reg.clone());
    reg
}

/// Liveness and a count. The ids are the artifacts' URLs: they are not
/// listed for whoever asks (audit of 2026-10-30, H3-1; the router's
/// `/healthz` says the same).
async fn api_list(State(ctx): State<Ctx>) -> impl IntoResponse {
    let reg = refresh_cache(&ctx).await;
    Json(json!({
        "serve_port": ctx.advertised_port,
        "artifacts": reg.artifacts.len(),
    }))
}

async fn artifact_root(
    State(ctx): State<Ctx>,
    AxPath(id): AxPath<String>,
    req: Request,
) -> Response {
    serve_artifact(&ctx, &id, "", req).await
}

async fn artifact_path(
    State(ctx): State<Ctx>,
    AxPath((id, rest)): AxPath<(String, String)>,
    req: Request,
) -> Response {
    serve_artifact(&ctx, &id, &rest, req).await
}

async fn serve_artifact(ctx: &Ctx, id: &str, rest: &str, req: Request) -> Response {
    let reg = refresh_cache(ctx).await;
    let Some(cv) = reg.artifacts.get(id).cloned() else {
        return (StatusCode::NOT_FOUND, format!("unknown artifact: {}", id)).into_response();
    };
    match cv.kind {
        ArtifactKind::Static => serve_static(&cv, rest).await,
        ArtifactKind::Service => serve_service(ctx, &cv, rest, req).await,
    }
}

// ── Static-file serving with symlink-escape hardening ───────────────────────

async fn serve_static(cv: &Artifact, rest: &str) -> Response {
    let rel = if rest.is_empty() { "index.html" } else { rest };

    // Coarse first pass: textual path-escape rejection.
    if rel.split('/').any(|seg| seg == "..") {
        return (StatusCode::FORBIDDEN, "path escape rejected").into_response();
    }

    let mut requested = PathBuf::from(&cv.root_path);
    for seg in rel.split('/').filter(|s| !s.is_empty()) {
        requested.push(seg);
    }
    if requested.is_dir() {
        requested.push("index.html");
    }

    // Symlink-escape hardening: even if the segments looked clean, a
    // symlink WITHIN the artifact dir could point outside (e.g. a file
    // generated by the agent, a link to a host file). Canonicalise
    // and require the result to remain under root_path.
    let root_canon = match std::fs::canonicalize(&cv.root_path) {
        Ok(p) => p,
        Err(_) => {
            return (StatusCode::INTERNAL_SERVER_ERROR, "artifact root vanished").into_response();
        }
    };
    let req_canon = match std::fs::canonicalize(&requested) {
        Ok(p) => p,
        Err(_) => {
            // File legitimately doesn't exist OR a broken symlink — return 404.
            return (
                StatusCode::NOT_FOUND,
                format!("not found: /a/{}/{}", cv.id, rel),
            )
                .into_response();
        }
    };
    if !is_under(&req_canon, &root_canon) {
        return (StatusCode::FORBIDDEN, "symlink escape rejected").into_response();
    }

    match tokio::fs::read(&req_canon).await {
        Ok(bytes) => {
            let mime = guess_mime(&req_canon);
            let mut h = HeaderMap::new();
            h.insert("content-type", HeaderValue::from_str(mime).unwrap());
            (StatusCode::OK, h, bytes).into_response()
        }
        Err(_) => (
            StatusCode::NOT_FOUND,
            format!("not found: /a/{}/{}", cv.id, rel),
        )
            .into_response(),
    }
}

fn is_under(child: &Path, parent: &Path) -> bool {
    child.starts_with(parent)
}

fn guess_mime(p: &Path) -> &'static str {
    match p
        .extension()
        .and_then(|e| e.to_str())
        .map(|s| s.to_ascii_lowercase())
        .as_deref()
    {
        Some("html") | Some("htm") => "text/html; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("js") | Some("mjs") => "text/javascript; charset=utf-8",
        Some("json") => "application/json",
        Some("svg") => "image/svg+xml",
        Some("png") => "image/png",
        Some("jpg") | Some("jpeg") => "image/jpeg",
        Some("gif") => "image/gif",
        Some("webp") => "image/webp",
        Some("ico") => "image/x-icon",
        Some("wasm") => "application/wasm",
        Some("woff") => "font/woff",
        Some("woff2") => "font/woff2",
        Some("txt") | Some("md") => "text/plain; charset=utf-8",
        _ => "application/octet-stream",
    }
}

// ── Reverse proxy for service artifacts ───────────────────────────────────────
//
// A `service` artifact is a long-running process (python http.server, node, …)
// spawned by `ArtifactServe` and bound to `127.0.0.1:<svc_port>` in our own
// process namespace. We forward `GET`/`HEAD /a/<id>/...` to it, the headers
// through the router's two allowlists and no body. The hop is intra-runtime
// (same trust domain); what crosses it came from a browser.

/// Request headers that travel to the service. Cookies, credentials and
/// anything else a browser attaches stay here.
const FORWARDED_REQUEST_HEADERS: &[&str] = &[
    "accept",
    "accept-language",
    "range",
    "if-none-match",
    "if-modified-since",
    "user-agent",
];

/// Response headers the browser gets back from the service. `guard` adds the
/// protective set on top.
const FORWARDED_RESPONSE_HEADERS: &[&str] = &[
    "content-type",
    "content-disposition",
    "content-range",
    "accept-ranges",
    "etag",
    "last-modified",
    "content-security-policy",
];

async fn serve_service(ctx: &Ctx, cv: &Artifact, rest: &str, req: Request) -> Response {
    let Some(spec) = &cv.service else {
        return (StatusCode::SERVICE_UNAVAILABLE, "service not started").into_response();
    };
    let Some(pid) = spec.pid else {
        return (StatusCode::SERVICE_UNAVAILABLE, "service has no PID").into_response();
    };
    if !artifact::pid_alive(pid) {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("service pid {} no longer alive", pid),
        )
            .into_response();
    }

    let upstream_path = if rest.is_empty() {
        String::new()
    } else {
        format!("/{}", rest)
    };
    let query = req
        .uri()
        .query()
        .map(|q| format!("?{}", q))
        .unwrap_or_default();
    let upstream = format!("http://127.0.0.1:{}{}{}", spec.port, upstream_path, query);

    // `guard` admitted GET or HEAD; nothing else reaches here.
    let method = if req.method() == Method::HEAD {
        reqwest::Method::HEAD
    } else {
        reqwest::Method::GET
    };
    let mut req_b = ctx.http.request(method, &upstream);
    for name in FORWARDED_REQUEST_HEADERS {
        for v in req.headers().get_all(*name) {
            if let Ok(val) = reqwest::header::HeaderValue::from_bytes(v.as_bytes()) {
                req_b = req_b.header(*name, val);
            }
        }
    }

    let resp = match req_b.send().await {
        Ok(r) => r,
        Err(e) => return (StatusCode::BAD_GATEWAY, format!("upstream: {}", e)).into_response(),
    };

    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let mut headers = HeaderMap::new();
    for name in FORWARDED_RESPONSE_HEADERS {
        for v in resp.headers().get_all(*name) {
            if let Ok(val) = HeaderValue::from_bytes(v.as_bytes()) {
                headers.append(axum::http::HeaderName::from_static(name), val);
            }
        }
    }
    let bytes = match resp.bytes().await {
        Ok(b) => b,
        Err(e) => {
            return (StatusCode::BAD_GATEWAY, format!("upstream body: {}", e)).into_response()
        }
    };

    (status, headers, Body::from(bytes)).into_response()
}

// ── Tests ────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use std::os::unix::fs::symlink;
    use tempfile::tempdir;

    /// Build a fake artifact directory with an `index.html` and an `evil`
    /// symlink to /etc/passwd, then verify `serve_static` returns 403 for the
    /// symlink and 200 for index.
    #[tokio::test]
    async fn symlink_escape_rejected() {
        let tmp = tempdir().unwrap();
        let root = tmp.path().to_path_buf();
        std::fs::write(root.join("index.html"), b"<h1>ok</h1>").unwrap();
        symlink("/etc/passwd", root.join("evil")).unwrap();

        let cv = Artifact {
            id: "cv_test".into(),
            name: None,
            kind: ArtifactKind::Static,
            state: x0ne_artifact::ArtifactState::Created,
            persistent: false,
            root_path: root.clone(),
            session_id: None,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
            service: None,
        };

        let ok = serve_static(&cv, "").await;
        assert_eq!(ok.status(), StatusCode::OK, "index should serve");

        let blocked = serve_static(&cv, "evil").await;
        assert_eq!(
            blocked.status(),
            StatusCode::FORBIDDEN,
            "symlink to outside root must be 403"
        );
    }

    #[tokio::test]
    async fn missing_file_is_404() {
        let tmp = tempdir().unwrap();
        let cv = Artifact {
            id: "cv_test".into(),
            name: None,
            kind: ArtifactKind::Static,
            state: x0ne_artifact::ArtifactState::Created,
            persistent: false,
            root_path: tmp.path().to_path_buf(),
            session_id: None,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
            service: None,
        };
        let r = serve_static(&cv, "nope.html").await;
        assert_eq!(r.status(), StatusCode::NOT_FOUND);
    }
}
